#!/usr/bin/env python3
"""INTENT1 analysis (planned/INTENT1_PREREG.md)."""
import json, glob
R = [json.loads(l) for f in glob.glob('out/intent1/*.jsonl') for l in open(f) if l.strip()]
M, VOLS, HK = ('houston', 'dfw'), ('V2', 'VL1', 'VL2'), ('A0', 'A2', 'M1', 'FLEX')
def sel(m, h, v, mode='cross', site='headline'): return [r for r in R if r['metro'] == m and r['heights'] == h and r['vol'] == v and r['mode'] == mode and r['sites'] == site]
def held(rows, op='all'):
    n = sum(r['cost'][op]['n'] for r in rows if op in r['cost']); return sum(r['cost'][op]['delayed'] + r['cost'][op]['cancelled'] for r in rows if op in r['cost']) / n if n else float('nan')
def H(m, h, v, mode='cross', op='all'): return held(sel(m, h, v, mode), op)
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
chk('I1', all(H(m, h, 'V2') < H(m, h, 'VL1') < H(m, h, 'VL2') for m in M for h in HK), '; '.join(f'{m} {h} ' + ' / '.join(f'{100 * H(m, h, v):.1f}' for v in VOLS) + ' %' for m in M for h in HK))
chk('I2', all(H(m, 'M1', 'VL1') < min(H(m, 'A2', 'VL1'), H(m, 'A0', 'VL1')) for m in M), '; '.join(f'{m} VL1 M1 {100 * H(m, "M1", "VL1"):.1f} / A2 {100 * H(m, "A2", "VL1"):.1f} / A0 {100 * H(m, "A0", "VL1"):.1f} %' for m in M))
rat = lambda m, v: H(m, 'A2', v) / H(m, 'M1', v)
chk('I3', all(rat(m, 'VL2') < rat(m, 'V2') for m in M), '; '.join(f'{m} A2/M1 V2 {rat(m, "V2"):.2f}, VL1 {rat(m, "VL1"):.2f}, VL2 {rat(m, "VL2"):.2f}' for m in M))
chk('I4', all(H(m, 'FLEX', v) < H(m, 'A0', v) for m in M for v in VOLS), '; '.join(f'{m} {v} FLEX {100 * H(m, "FLEX", v):.1f} vs A0 {100 * H(m, "A0", v):.1f} %' for m in M for v in VOLS))
chk('I5', all(H(m, 'FLEX', 'VL2') < H(m, 'M1', 'VL2') for m in M), '; '.join(f'{m} VL2 FLEX {100 * H(m, "FLEX", "VL2"):.1f} vs M1 {100 * H(m, "M1", "VL2"):.1f} %' for m in M))
chk('I6', all(H(m, 'M1', 'V2', 'own') >= H(m, 'A2', 'V2', 'own') for m in M), '; '.join(f'{m} own-fleet V2: M1 {100 * H(m, "M1", "V2", "own"):.1f} vs A2 {100 * H(m, "A2", "V2", "own"):.1f} % (FLEX {100 * H(m, "FLEX", "V2", "own"):.1f} %)' for m in M))
chk('I7', all(H(m, 'M1', 'V2', 'own', 'wing') >= 2 * H(m, 'A2', 'V2', 'own', 'wing') for m in M), '; '.join(f'{m} Wing held, own-fleet: M1 {100 * H(m, "M1", "V2", "own", "wing"):.1f} vs A2 {100 * H(m, "A2", "V2", "own", "wing"):.1f} %' for m in M))
T = {m: [r for r in R if r['metro'] == m and r['sites'] != 'headline'] for m in M}
chk('I8', all(t and held(t) < 0.02 and all(r['wideCross'] == 0 for r in t) for t in T.values()), '; '.join(f'{m} ({t[0]["sites"] if t else "-"}) held {100 * held(t):.2f} %, flown conflicts {[r["wideCross"] for r in t]}' for m, t in T.items()))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# INTENT1 results table (generated by planned/intent1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Runs: {len(R)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Held share (delayed or cancelled), different companies checked', '', '| Metro | Heights | Volume | Held | Wing | Zipline | Amazon | Cancelled | Moved (FLEX) | Flown conflicts between companies /h | within companies /h |', '|---|---|---|---|---|---|---|---|---|---|---|']
for m in M:
    for h in HK:
        for v in VOLS:
            x = sel(m, h, v); n = sum(r['cost']['all']['n'] for r in x); c = sum(r['cost']['all']['cancelled'] for r in x); mv = sum(r['moved']['n'] for r in x)
            L.append(f'| {m} | {h} | {v} | {100 * held(x):.1f} % | {100 * held(x, "wing"):.1f} % | {100 * held(x, "zipline"):.1f} % | {100 * held(x, "amazon"):.1f} % | {100 * c / n:.1f} % | {100 * mv / n:.1f} % | {sum(r["wideCross"] for r in x) / 10:.2f} | {sum(sum(r["wideOwn"].values()) for r in x) / 10:.1f} |')
L += ['', '## Own fleets checked too (V2)', '', '| Metro | Heights | Held | Wing | Zipline | Amazon | Within-company flown conflicts /h, not checked -> checked |', '|---|---|---|---|---|---|---|']
for m in M:
    for h in ('A2', 'M1', 'FLEX'):
        x, y = sel(m, h, 'V2', 'own'), sel(m, h, 'V2')
        L.append(f'| {m} | {h} | {100 * held(x):.1f} % | {100 * held(x, "wing"):.1f} % | {100 * held(x, "zipline"):.1f} % | {100 * held(x, "amazon"):.1f} % | ' + ', '.join(f'{op} {sum(r["wideOwn"][op] for r in y) / 10:.1f} -> {sum(r["wideOwn"][op] for r in x) / 10:.1f}' for op in ('wing', 'zipline', 'amazon')) + ' |')
L += ['', '## Today / early stage (A0, V2)', '']
for m, t in T.items(): L.append(f'- {m}: stage {t[0]["sites"] if t else "-"}, runs {len(t)}, flights checked {sum(r["checked"] for r in t)}, held {100 * held(t):.2f} %, flown conflicts between companies {[r["wideCross"] for r in t]}')
open('planned/intent1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
